input.function:
() => {
  const rows = document.querySelectorAll('table tbody tr, table tr');
  for (const row of rows) {
    const text = row.textContent || '';
    if (text.includes('STLOW')) {
      const links = row.querySelectorAll('a');
      const linkInfo = [];
      for (const a of links) {
        linkInfo.push({ href: a.href, text: a.textContent.trim() });
      }
      return { rowText: text.trim(), links: linkInfo, html: row.outerHTML.slice(0, 2000) };
    }
  }
  return 'STLOW row not found';
}

